package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.TosUriVO;

class TosUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tos uri of oauth client")
  void test_tos_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    TosUriValueHolder<Object> value = new TosUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.tosUri("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getTosUriValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getTosUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.tosUriNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTosUriValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getTosUri().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tos uri of oauth client")
  void test_tos_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    TosUriValueHolder<Object> value = new TosUriValueHolder<>(holder);
    TosUriVO vo = TosUriVO.from("one");
    Assertions.assertFalse(value.getTosUriValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.tosUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTosUriValue().orElseThrow());
    Assertions.assertSame(holder, value.tosUri(Optional.empty()));
    Assertions.assertFalse(value.getTosUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tosUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTosUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tos uri of oauth client against the original")
  void test_tos_uri_value_holder_read() {
    Object holder = new Object();
    TosUriValueHolder<Object> value = new TosUriValueHolder<>(holder);
    TosUriVO vo = TosUriVO.from("one");
    TosUriVO other = TosUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getTosUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTosUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTosUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.tosUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTosUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTosUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tos uri of oauth client")
  void test_tos_uri_value_holder_unset() {
    Object holder = new Object();
    TosUriValueHolder<Object> value = new TosUriValueHolder<>(holder);
    TosUriVO vo = TosUriVO.from("one");
    value.tosUri(vo);
    Assertions.assertSame(holder, value.unsetTosUriIfMatches("tosUri_other"));
    Assertions.assertTrue(value.getTosUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTosUriIfMatches("tosUri"));
    Assertions.assertFalse(value.getTosUriValue().isPresent(),
        "The field name must clear the value");
    value.tosUri(vo);
    Assertions.assertSame(holder, value.unsetTosUri());
    Assertions.assertFalse(value.getTosUriValue().isPresent(), "Unset must clear the value");
  }
}
